mapper.select:
SELECT si.sku_id as skuId, sku.sku_name as skuName, sku.sku_code as skuCode, p.product_name as productName, p.product_type as productType, SUM(si.quantity) as totalQuantity, SUM(si.subtotal) as totalAmount FROM e_wms_sales_item si INNER JOIN e_wms_sales_order so ON si.order_id = so.id INNER JOIN e_wms_sku sku ON si.sku_id = sku.id INNER JOIN e_wms_product p ON sku.product_id = p.id WHERE si.is_delete = 0 AND so.status = 1 AND so.is_delete = 0
AND so.create_at >= #{startDate}
AND so.create_at <= CONCAT(#{endDate}, ' 23:59:59')
AND so.customer_id = #{customerId}
GROUP BY si.sku_id, sku.sku_name, sku.sku_code, p.product_name, p.product_type ORDER BY totalAmount DESC

SELECT so.customer_id as customerId, c.customer_name as customerName, c.customer_phone as customerPhone, c.customer_type as customerType, COUNT(DISTINCT so.id) as orderCount, SUM(si.quantity) as totalQuantity, SUM(si.subtotal) as totalAmount FROM e_wms_sales_item si INNER JOIN e_wms_sales_order so ON si.order_id = so.id LEFT JOIN e_wms_customer c ON so.customer_id = c.id WHERE si.is_delete = 0 AND so.status = 1 AND so.is_delete = 0
AND so.create_at >= #{startDate}
AND so.create_at <= CONCAT(#{endDate}, ' 23:59:59')
AND so.customer_id = #{customerId}
GROUP BY so.customer_id, c.customer_name, c.customer_phone, c.customer_type ORDER BY totalAmount DESC

SELECT SUM(si.quantity) as totalQuantity, SUM(si.subtotal) as totalAmount, COUNT(DISTINCT so.id) as orderCount, COUNT(DISTINCT si.sku_id) as productCount FROM e_wms_sales_item si INNER JOIN e_wms_sales_order so ON si.order_id = so.id WHERE si.is_delete = 0 AND so.status = 1 AND so.is_delete = 0
AND so.create_at >= #{startDate}
AND so.create_at <= CONCAT(#{endDate}, ' 23:59:59')
AND so.customer_id = #{customerId}
